# LOCAL-ONLY override - gitignored. DO NOT COMMIT.
# Stack agenta-ee-dev-sharing (agenta-sharing, sharing program overnight build). Private image tags so a
# --build here does not replace the shared agenta-ee-dev-*:latest tags other checkouts use.
# The classic app (web, /w) runs too: the build rules require /w live QA. /m is web-mobile.
x-api-image: &api-image agenta-ee-dev-sharing-api:latest
x-web-image: &web-image agenta-ee-dev-sharing-web:latest
services:
    .api: { image: *api-image }
    .web: { image: *web-image }
    .services: { image: agenta-ee-dev-sharing-services:latest }
    .runner: { image: agenta-ee-dev-sharing-runner:latest }
    api: { image: *api-image }
    worker-streams: { image: *api-image }
    worker-queues: { image: *api-image }
    cron: { image: *api-image }
    alembic: { image: *api-image }
    mock-llm-gateway: { image: *api-image }
    mock-mcp-gateway: { image: *api-image }
    services: { image: agenta-ee-dev-sharing-services:latest }
    runner: { image: agenta-ee-dev-sharing-runner:latest }
    web-mobile: { image: *web-image }
    # web (the classic app, served at /w) re-enabled 2026-10-22 for /w QA (HANDOFF hard rule)
    web:
        image: *web-image
